<?php
declare(strict_types=1);
function financeTeamCreditBalance(PDO $pdo,int $player):int{$s=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN m.kind='deposit' THEN m.amount ELSE -m.amount END),0) FROM finance_team_credit_movements m LEFT JOIN finance_entries e ON e.id=m.entry_id WHERE m.player_id=? AND m.status='active' AND (m.entry_id IS NULL OR e.status='paid')");$s->execute([$player]);return financeTeamSignedCents((string)$s->fetchColumn());}
function financeTeamChargeReceivedSql(string $alias='c'):string{if(!preg_match('/^[a-z]+$/D',$alias))throw new LogicException();return "(COALESCE((SELECT SUM(e.amount) FROM finance_team_charge_payments p JOIN finance_entries e ON e.id=p.entry_id WHERE p.charge_id=$alias.id AND e.status='paid'),0)+COALESCE((SELECT SUM(w.amount) FROM finance_team_credit_movements w WHERE w.charge_id=$alias.id AND w.kind='use' AND w.status='active'),0))";}
function financeTeamCreditAudit(PDO $pdo,int $id,string $action,int $actor,?string $reason=null):void{$s=$pdo->prepare('SELECT * FROM finance_team_credit_movements WHERE id=?');$s->execute([$id]);$row=$s->fetch(PDO::FETCH_ASSOC);$pdo->prepare('INSERT INTO finance_team_credit_history(movement_id,action,actor_user_id,reason,snapshot_json) VALUES(?,?,?,?,?)')->execute([$id,$action,$actor,$reason,json_encode($row,JSON_THROW_ON_ERROR)]);}
function financeTeamCreditRecord(PDO $pdo,array $input,int $actor,?array $request=null):int{
 $kind=(string)($input['kind']??'');if(!in_array($kind,['deposit','refund','use'],true)||$actor<=0)throw new DomainException('Operacao invalida.');
 $owner=financeTeamParty($pdo,['team_party_kind'=>'player','team_player_id'=>$input['credit_player_id']??null]);$player=(int)$owner['party_id'];$amount=financeTeamCents((string)($input['amount']??''));if($amount<=0)throw new DomainException('Valor invalido.');$date=(string)($input['paid_at']??'');if(!financeTeamDate($date))throw new DomainException('Data invalida.');
 $method=(string)($input['payment_method']??'');if($method!==''&&!array_key_exists($method,financePaymentMethodOptions()))throw new DomainException('Forma de pagamento invalida.');$payer=$kind==='use'||$kind==='refund'?$owner:financeTeamParty($pdo,$input);$chargeId=$kind==='use'?(int)($input['charge_id']??0):null;$accountId=(int)($input['account_id']??0);$key=(string)($input['request_key']??'');if(!preg_match('/^[a-f0-9]{64}$/D',$key))throw new DomainException('Reabra o formulario.');$fp=hash('sha256',json_encode([$kind,$owner,$payer,$amount,$date,$chargeId,$accountId,$actor]));
 financeTeamTransaction($pdo);
 try{
  $s=$pdo->prepare('SELECT id,fingerprint FROM finance_team_credit_movements WHERE request_key=?');$s->execute([$key]);$old=$s->fetch(PDO::FETCH_ASSOC);if($old){if(!hash_equals($old['fingerprint'],$fp))throw new DomainException('Envio ja utilizado.');$pdo->commit();return (int)$old['id'];}
  if($request){$s=$pdo->prepare('SELECT status FROM finance_wallet_requests WHERE id=? FOR UPDATE');$s->execute([$request['id']]);if($s->fetchColumn()!=='pending')throw new DomainException('Solicitacao ja revisada.');}
  if($kind!=='deposit'&&financeTeamCreditBalance($pdo,$player)<$amount)throw new DomainException('Credito insuficiente para esta operacao.');
  $entryId=null;$before=null;
  if($kind==='use'){$s=$pdo->prepare('SELECT id FROM finance_team_charges WHERE id=? FOR UPDATE');$s->execute([$chargeId]);$before=financeTeamChargeSnapshot($pdo,(int)$chargeId);if($before['status']!=='open'||$amount>financeTeamCents($before['remaining_amount']))throw new DomainException('Valor maior que a cobranca em aberto.');}
  else{$pdo->prepare("INSERT INTO finance_entries(type,title,description,amount,party_type,party_module,party_id,party_name,paid_at,status,source,payment_method,receipt_path,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,?,?,?,?,'paid',?,?,?,?,?)")->execute([$kind==='deposit'?'income':'expense',$kind==='deposit'?'Credito antecipado':'Devolucao de credito','Credito de '.$owner['party_name'],financeTeamDecimal($amount),$payer['party_type'],$payer['party_module'],$payer['party_id'],$payer['party_name'],$date,$kind==='deposit'?'team_credit_deposit':'team_credit_refund',$method?:null,$request['receipt_path']??null,$actor,$actor]);$entryId=(int)$pdo->lastInsertId();financeTeamAudit($pdo,$entryId,'created',$actor,null,null,$accountId);}
  $pdo->prepare('INSERT INTO finance_team_credit_movements(player_id,player_name,kind,amount,entry_id,charge_id,movement_date,actor_user_id,request_key,fingerprint) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$player,$owner['party_name'],$kind,financeTeamDecimal($amount),$entryId,$chargeId,$date,$actor,$key,$fp]);$id=(int)$pdo->lastInsertId();financeTeamCreditAudit($pdo,$id,'created',$actor);
  if($before)financeTeamChargeAudit($pdo,(int)$chargeId,'credit_applied',$actor,$before);
  if($request)$pdo->prepare("UPDATE finance_wallet_requests SET status='approved',reviewed_by_user_id=?,reviewed_at=NOW() WHERE id=?")->execute([$actor,$request['id']]);
  $pdo->commit();return $id;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function financeTeamCreditCancelUse(PDO $pdo,int $id,string $reason,int $actor):void{if($actor<=0)throw new DomainException('Responsavel invalido.');$reason=financeTeamReason($reason);financeTeamTransaction($pdo);try{$s=$pdo->prepare('SELECT * FROM finance_team_credit_movements WHERE id=?');$s->execute([$id]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row||$row['kind']!=='use')throw new DomainException('Quitacao nao encontrada.');if($row['status']==='active'){$before=financeTeamChargeSnapshot($pdo,(int)$row['charge_id']);$pdo->prepare("UPDATE finance_team_credit_movements SET status='canceled' WHERE id=?")->execute([$id]);financeTeamCreditAudit($pdo,$id,'canceled',$actor,$reason);financeTeamChargeAudit($pdo,(int)$row['charge_id'],'credit_canceled',$actor,$before,null,$reason);}$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
